quests[37413] = { id = 37413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gnarljaw" }
quests[37416] = { id = 37416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festmahl der Spitzen", description = "<Scheff/Scheffin>, ich hab 'n echtes Festmahl für Euch da drüben aufgefahr'n. Ihr solltet 'nen Bissen zu Euch nehmen, bevor Ihr aufbrecht.\n\nVertraut mir, danach werdet Ihr Euch viel besser fühl'n!", sourceObjective = "Nehmt ein Festmahl der Spitzen in Axtfall zu Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37417] = { id = 37417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festmahl der Spitzen", description = "Ich hab' ein echtes Festmahl für Euch da drüben aufgefahren, Kommandant. Ihr solltet 'nen Bissen zu Euch nehmen, bevor Ihr aufbrecht.\n\nGlaubt mir, danach werdet Ihr Euch besser fühl'n.", sourceObjective = "Nehmt ein Festmahl der Spitzen in Südhafen zu Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37418] = { id = 37418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll ausgestattet und einsatzbereit", description = "Großartige Neuigkeiten, Kommandant! Jetzt, da die Werkstatt voll ausgestattet und einsatzbereit ist, können wir Belagerungswaffen wie am Fließband herstellen – sobald wir die Materialien haben.\n\nDer überladene Verwüster ist das Sahnestück goblinischer Ingenieurskunst, wenn ich das mal selbst so sagen darf. Mächtiger als der Durchschnittsverwüster, und man kann ihn fast überall einsetzen! Die einzige Einschränkung besteht in der beschränkten Menge an Treibstoff, die wir im Chassis unterbringen können.\n\nWenn Ihr bereit seid, mit der Produktion zu beginnen, dann bringt uns einfach ein paar Rohstoffe und gebt die Bestellung auf!", sourceObjective = "Erteilt in der Werkstatt Eurer Garnison einen Arbeitsauftrag.", completion = "Ich kann's kaum erwarten, Euch das Schätzchen zu zeigen, wenn es fertig ist, Kommandant!\n\nKommt morgen wieder und vergesst bloß nicht Eure Schutzbrille!", sourceObjectiveStatus = "unverified-source-field" }
quests[37420] = { id = 37420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll ausgestattet und einsatzbereit", description = "Großartige Neuigkeiten, Kommandant! Jetzt, da die Werkstatt voll ausgestattet und einsatzbereit ist, können wir Belagerungswaffen wie am Fließband herstellen – sobald wir die Materialien haben.\n\nDie überladene Belagerungsmaschine ist das Sahnestück gnomischer Ingenieurskunst, wenn ich das mal selbst so sagen darf. Mächtiger als normale Belagerungsmaschinen, und man kann sie fast überall einsetzen! Die einzige Einschränkung besteht in der beschränkten Menge an Treibstoff, die wir im Chassis unterbringen können.\n\nWenn Ihr bereit seid, mit der Produktion zu beginnen, dann bringt uns einfach ein paar Rohstoffe und gebt die Bestellung auf!", sourceObjective = "Erteilt in der Werkstatt Eurer Garnison einen Arbeitsauftrag.", completion = "Ich kann's kaum erwarten, Euch das Schätzchen zu zeigen, wenn es fertig ist, Kommandant!\n\nKommt morgen wieder und vergesst bloß nicht Eure Schutzbrille!", sourceObjectiveStatus = "unverified-source-field" }
