quests[37432] = { id = 37432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[37433] = { id = 37433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuerprobe", description = "Ich grüße Euch, Kommandant.\n\nDie Kunde Eurer Taten hat auch Prüfungsmeister Rotun erreicht, und er bittet in aller Bescheidenheit, Euer Können selbst in Augenschein nehmen zu dürfen. Stellt Euch seiner Feuerprobe, um Euren Ruf innerhalb der Allianz und darüber hinaus zu verbreiten.\n\nWenn Ihr daran interessiert seid, Euch zu beweisen, dann sprecht mich an und ich gewähre Euch Zugang zur Feuerprobe von Prüfungsmeister Rotun.", sourceObjective = "Sprecht mit Leutnant Dorn, um die Feuerprobe zu beginnen, und schließt eine Bronzeprüfung ab.", progress = "Habt Ihr Eure Herausforderung absolviert?", completion = "Glückwunsch, Kommandant. Ihr habt Rotuns Prüfung überlebt und Eure Stärke wahrlich unter Beweis gestellt.\n\nHier, nehmt diese Waffe, auf dass Ihr auch weiterhin Eure Gegner im Kampf dominiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[37434] = { id = 37434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuerprobe", description = "Ich grüße Euch, Kommandant.\n\nDie Kunde Eurer Taten hat auch Prüfungsmeister Rotun erreicht, und er bittet in aller Bescheidenheit, Euer Können selbst in Augenschein nehmen zu dürfen. Stellt Euch seiner Feuerprobe, um Euren Ruf innerhalb der Horde und darüber hinaus zu verbreiten.\n\nWenn Ihr daran interessiert seid, Euch zu beweisen, dann sprecht mich an und ich gewähre Euch Zugang zur Feuerprobe von Prüfungsmeister Rotun.", sourceObjective = "Sprecht mit Kriegsmeister Zog in Eurer Garnison, um die Feuerprobe zu beginnen, und schließt eine Bronzeprüfung ab.", progress = "Habt Ihr Eure Herausforderung absolviert?", completion = "Glückwunsch, Kommandant. Ihr habt Rotuns Prüfung überlebt und Eure Stärke wahrlich unter Beweis gestellt.\n\nHier, nehmt diese Waffe, auf dass Ihr auch weiterhin Eure Gegner im Kampf dominiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[37435] = { id = 37435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 084 - Spirit Coffer" }
quests[37439] = { id = 37439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstillbarer Durst", description = "Wenn es eine Lektion von Eurer Zeit auf der Insel der Sonnenwanderer gibt, die Ihr niemals vergessen dürft, dann ist es diese: Verliert unter keinen Umständen die Kontrolle über Euer Verlangen nach Magie. Dieser Durst ist unstillbar, {name}. Verwendet den arkanen Strom, um das, was Ihr absorbiert, zu kontrollieren und in der von Euch gewünschten Form wieder freizulassen. Begeht Ihr dabei einen Fehler, werdet Ihr zu einem Getriebenen... hoffnungslos abhängig und dem Wahnsinn verfallen.\n\nSucht nach einem Manawyrm und fokussiert Euren Manadurst auf ihn. Lernt, Eure Macht zu kontrollieren. Kehrt zu mir zurück, wenn Ihr einen arkanen Strom entfesselt habt – und das zufriedenstellend.", sourceObjective = "Verwendet die Volksfähigkeit 'Arkaner Strom' auf einen Manawyrm und kehrt anschließend zu Arkanist Helion zurück.", completion = "Ihr habt Euch heute bewiesen, {name}. Eurer Wille zu lernen zeigt, dass Ihr Euch sehr wohl gegenüber dem endlosen Verlangen, welches jeden Blutelfen beherrscht, durchsetzen könnt.\n\nRuht Euch nicht auf Euren Lorbeeren aus, sondern versucht zu meistern, was Ihr gelernt habt. Nur durch Tatendrang können wir als Volk überleben.\n\nNehmt dies – es wird Euch von Nutzen sein. Geht nun und macht unserem Volk noch einmal Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[37440] = { id = 37440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für eine Handvoll Fragmente", description = "Es ist eine Schande, dass wir die Kontrolle über so viele Kreaturen hier auf der Insel verloren haben. Es war einst ein ruhiger Ort der Studien und Forschungsarbeiten. Jetzt können wir uns nur noch hüten, damit wir von unseren eigenen Kreationen nicht angegriffen werden!\n\nIch biete Euch einen magischen Segen an, wenn Ihr für mich etwas einsammelt. Bringt mir eine Handvoll Arkanspäne von den Mana benutzenden Kreaturen der Insel der Sonnenwanderer und ich wirke einen Zauber auf Euch, welcher Eure weiteren Abenteuer immens erleichtern wird.", sourceObjective = "Sammelt 6 Arkanspäne und bringt sie zu Arkanist Ithanas auf der Insel der Sonnenwanderer. Derartige Fragmente findet man bei allen Mana benutzenden Kreaturen auf der Insel.", progress = "Einst waren uns viele der Lebewesen auf dieser Insel friedlich gesinnt, unsere Magie hielt sie in einem permanenten Zustand der Kontrolle. Doch mit der Zerstörung des Sonnenbrunnens durch die Geißel verloren wir auch unsere Kontrolle über sie. Die Arkanspäne sind das letzte Überbleibsel unserer damaligen Beherrschungsmagie, und als solche können sie uns vielleicht bei der Erschaffung eines neuen Artefakts helfen, mit dessen Macht wir die Kontrolle zurückerlangen werden.\n\nNoch wichtiger, mithilfe der Fragmente könnten wir herausfinden, unter welchem Fluch diese Insel wirklich leidet...", completion = "Großartig, die werden ihren Zweck erfüllen! Ursprünglich habe ich diesen abgelegenen Ort aufgesucht, um in aller Ruhe nachzudenken und zu erforschen, unter welchem Fluch die Insel der Sonnenwanderer leidet. Eine der Möglichkeiten, die ich in Betracht zog, war das Sammeln der Arkanspäne von den Wildtieren auf der Insel. Mit ihnen wollte ich experimentieren, um eine mögliche Ursache zu entdecken.\n\nWie auch immer, ich werde mich weiter auf meine Forschungen konzentrieren. Erlaubt mir, diesen Zauber auf Euch zu wirken. Ich denke, Ihr werdet ihn sehr nützlich finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[37441] = { id = 37441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solanians Habe", description = "Bei dem Chaos hier beim Sonnenturm, habe ich es nicht geschafft, all mein Hab und Gut zusammenzusammeln, das ich an verschiedenen Plätzen auf der Insel gelassen habe. Ich muss hier beim Sonnenbrunnen weiterhin Wache halten, aber könntet Ihr vielleicht meine Sachen an meiner Stelle suchen gehen?\n\nIch brauche meine Seherkugel, meine Rolle der Geißelmagie und mein Tagebuch. Nutzt diesen Ranzen für zusätzliches Gepäck, da die Dinge etwas sperrig sind. Bringt sie zu mir zurück und ich gebe Euch dafür etwas im Austausch - für Eure Mühe, versteht Ihr? Den Ranzen könnt Ihr dann auch behalten!", sourceObjective = "Sammelt Brunnenbehüter Solanians Seherkugel, seine Rolle der Geißelmagie und sein Tagebuch ein. Ihr findet die Gegenstände auf der Insel der Sonnenwanderer bei dem Tümpel, dem Brunnen und bei einem der brennenden Kristalle. Bringt sie zu dem Brunnenbehüter oben im Sonnenturm auf der Insel der Sonnenwanderer, sobald Ihr alle gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[37442] = { id = 37442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein von Dath'Remar", description = "Tag für Tag stehe ich hier, beobachte, warte. Man hat mich beschuldigt, zu tief in unserer Vergangenheit zu graben, während mein Blick zum Horizont gerichtet ist. Ich glaube jedoch fest daran, dass jeder Besucher dieser Insel diejenigen ehren sollte, die alles dafür geopfert haben, damit andere fortfahren können.\n\nDath'Remar Sonnenwanderer war unser erster König. Er führte uns durch den Mahlstrom von Kalimdor hierher.\n\nSucht seinen Schrein im Westen auf und kehrt erst dann zu mir zurück, wenn Ihr die dort angebrachte Tafel zu seiner Ehre gelesen habt.", sourceObjective = "Lest die Tafel am Schrein von Dath'Remar und kehrt anschließend zu Brunnenbehüter Solanian beim Sonnenturm auf der Insel der Sonnenwanderer zurück.", completion = "Ah, {name} – Danke, dass Ihr mir von Euren Beobachtungen beim Schrein von Dath'Remar erzählt habt. Euer Forscherdrang hat uns und Euch heute ausgezeichnete Dienste geleistet. Ich bin sicher, er wird Euch nicht nur hier, sondern in ganz Azeroth von Nutzen sein.\n\nWas Eure merkwürdigen Empfindungen beim Schrein angeht, ich denke, dass sich dort ein Teil der Verderbnis eingenistet hat, die die gesamte Insel der Sonnenwanderer bedroht. Wir werden die Sache im Auge behalten; danke, dass Ihr uns alarmiert habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[37443] = { id = 37443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solanians Habe", description = "Bei dem Chaos hier beim Sonnenturm, habe ich es nicht geschafft, all mein Hab und Gut zusammenzusammeln, das ich an verschiedenen Plätzen auf der Insel gelassen habe. Ich muss hier beim Sonnenbrunnen weiterhin Wache halten, aber könntet Ihr vielleicht meine Sachen an meiner Stelle suchen gehen?\n\nIch brauche meine Seherkugel, meine Rolle der Geißelmagie und mein Tagebuch. Nutzt diesen Ranzen für zusätzliches Gepäck, da die Dinge etwas sperrig sind. Bringt sie zu mir zurück und ich gebe Euch dafür etwas im Austausch – für Eure Mühe, versteht Ihr? Den Ranzen könnt Ihr dann auch behalten!", sourceObjective = "Sammelt Brunnenbehüter Solanians Seherkugel, seine Rolle der Geißelmagie und sein Tagebuch ein. Ihr findet die Gegenstände auf der Insel der Sonnenwanderer bei dem Tümpel, dem Brunnen und bei einem der brennenden Kristalle. Bringt sie zu dem Brunnenbehüter oben im Sonnenturm auf der Insel der Sonnenwanderer, sobald Ihr alle gefunden habt.", progress = "Habt Ihr meine Sachen finden können? Sobald wir unsere Herrschaft über die Insel der Sonnenwanderer wiedererlangt haben, werde ich sie für meine Arbeit benötigen. Vorerst muss ich noch über den Sonnenbrunnen wachen... oder was davon übrig ist.", completion = "Gut gemacht – ich wusste, dass Ihr für diese Aufgabe geeignet sein würdet. Sobald wir uns auf der Insel wieder frei bewegen können, werde ich meine Sachen gut einsetzen.\n\nWie ich schon sagte, Ihr könnt den Ranzen behalten. Außerdem könnte auch dieses Rüstungsteil von Nutzen für Euch sein. Betrachtet es als großzügige Entlohnung für eine einfache Pflichterfüllung!", sourceObjectiveStatus = "unverified-source-field" }
quests[37444] = { id = 37444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immunisieren", description = "Zhanaa braucht unsere Hilfe, um Teile aus der Exodar zu bergen. Taerix hat eine Immunisierungsmethode vorbereitet, mit der die Nisteleulkins behandelt werden können. Sie bewohnen die Gegend, in der die meisten Teile gefunden werden können.\n\nNähert Euch den noch nicht verseuchten Biestern und wendet den Kristall auf sie an. Die anderen müsst Ihr leider umbringen. Ihr findet sie im Nisteldickicht und bei den Nistelhügeln im Südosten.", sourceObjective = "Wendet den Immunisierungskristall auf 6 Nisteleulkin an. Kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am'mental zurück.", progress = "Je mehr wir tun können, um den Nistelwald aufzuräumen, desto schneller kann Zhanaa zurück an die Arbeit.", completion = "Da jetzt viele der Eulkin immunisiert wurden, können wir uns auf unseren Aufbruch von hier konzentrieren, ohne die gesamte Eulkinpopulation ausrotten zu müssen.\n\nHier, sucht Euch etwas aus. Ihr habt eine so wunderbare Arbeit geleistet, Ihr verdient eine Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[37445] = { id = 37445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile", description = "Wir konnten einen beschädigten holografischen Emitter nach dem Absturz bergen. Sollten wir ihn reparieren können, besteht die Möglichkeit, dass wir noch andere Überlebende außerhalb des Am'mentals finden.\n\nVon dem Schiff hätte man einige Apparaturen sichern können, die geeignete Ersatzteile geliefert hätten, aber die heimischen Eulkin haben sie verschleppt, bevor wir sie überhaupt erreichen konnten.\n\n{name}, Ihr müsst ins Nisteldickicht und in die Nistelhügel im Süden gehen und die Ersatzteile zurückholen!", sourceObjective = "Beschafft 4 Emitterersatzteile und kehrt anschließend zu Technikerin Zhanaa bei der Absturzstelle im Am'mental zurück.", progress = "Ich bin mir sicher, dass wir den Emitter mit den Ersatzteilen reparieren können! Mit etwas Glück, werden wir da draußen noch andere finden, mit denen wir uns in Verbindung setzen können.", completion = "Lasst mich mal sehen.\n\nJa, ich denke, das wird gehen; gute Arbeit, {name}! Der Emitter ist ziemlich komplex und deshalb kann die Reparatur ein Weilchen dauern. Ich sage Euch Bescheid, sobald ich fertig bin.\n\nSchaut in der Zwischenzeit bei Verteidiger Aldar vorbei und fragt ihn, ob er Euch brauchen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[37446] = { id = 37446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faule Peons", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, {race}. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nHaltet unter den Bäumen im Tal nach ihnen Ausschau. Verdammte faule Peons...", sourceObjective = "Benutzt den Totschläger des Großknechts an 4 faulen Peons, wenn sie schlafen.", progress = "Verdammter fauler B...\n\nHuch? Habt Ihr meinen Totschläger? Habt Ihr Peons dabei erwischt, wie sie bei der Arbeit schliefen?!", completion = "Gut, gut. Vielleicht werden sie es sich in Zukunft zweimal überlegen, bevor sie wieder nachlässig werden! Ich danke Euch für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[37447] = { id = 37447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut der Dämonen", description = "Es ist an der Zeit, Kontakt mit der Seele des Meisters aufzunehmen. Sie befindet sich irgendwo in den endlosen Weiten des Wirbelnden Nethers. Aber Mardum eben auch.\n\nWas wir vorhaben, würde ich zwar nicht als unmöglich bezeichnen, aber es wird äußerst schwierig, selbst hier. Neben den Sachen, die uns die Matronenmutter zusammensuchen ließ, benötigen wir noch eine Menge Dämonenblut.\n\nEine gewaltige Menge!", sourceObjective = "Sammelt 100 Einheiten Teufelsblut von Dämonen auf den Verheerten Inseln.", progress = "Sobald wir genug Dämonenblut haben, könnt Ihr mit dem Ritual beginnen.", completion = "Wenn das jetzt nicht genug Dämonenblut ist, wird es niemals reichen. Nun lasst uns versuchen, mit Illidans Geist im Wirbelnden Nether Verbindung aufzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37448] = { id = 37448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein simpler Plan", description = "Wie viele Schreckenslords kann auch Detheroc sich Prahlereien nicht verkneifen. Aber er war unvorsichtig, und ich konnte viele seiner Pläne belauschen, als sie mich gefangen hielten.\n\nMit Eurer Erlaubnis möchte ich noch einmal betonen, wie prekär die Lage in Sturmwind ist. Das Schicksal von ganz Azeroth steht auf dem Spiel.\n\nAber für all das habe ich einen ganz simplen Plan: Auf sie mit Gebrüll.", sourceObjective = "Hört Euch den Plan von Mathias Shaw an und gebt dann Eure Stimme ab.", completion = "Die Entscheidung steht also. Wir müssen Detheroc enttarnen oder es kommt zu einem Krieg zwischen der Allianz und der Horde. Dann verlieren wir die ganze Welt an die Brennende Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[37449] = { id = 37449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Offenbarungen", description = "Damit wird Cordana Teufelsang nicht davonkommen. Ich werde nicht zulassen, dass diese Wächterhexe mein Volk gegen uns aufbringt.\n\nUnd was diese Nachtgleve betrifft... Verrätern gewähre ich KEINERLEI Gnade.\n\nWerdet Ihr mir helfen, {name}?", sourceObjective = "Tötet Nachtgleve die Verräterin.", completion = "Das sind in der Tat bittere Neuigkeiten. Wir können es uns nicht leisten, Dämonenjäger zu verlieren, aber Ihr und Kor'vas habt Nachtgleve zu Recht getötet.\n\nUnd noch wichtiger ist es, dass Ihr Freundschaft mit Stellagosa geschlossen habt. Die Überlebenden des blauen Drachenschwarms könnten mächtige Verbündete sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[37450] = { id = 37450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellagosas Rettung", description = "Mitten im Kampfgetümmel entdeckte ich plötzlich einen blauen Drachen, der sich auf die Dämonen stürzte. Ich konnte meinen Augen kaum glauben, denn ich hatte gehört, der blaue Drachenschwarm sei ausgestorben.\n\nDie Legion konnte den Drachen zwar überwältigen, aber zuvor hatte er jede Menge ihrer Kämpfer getötet. Ein wundervolles Geschöpf. Ich sah dann, wie sie den Drachen in Richtung ihres südlichen Lagers davonschleppten.\n\nWir sollten nachschauen, ob der Drache noch lebt. Er könnte ein wichtiger Verbündeter für uns werden.", sourceObjective = "Beschafft Lykills Schlüssel und befreit Stellagosa.", progress = "Wenn es hier noch Überlebende des blauen Drachenschwarms geben sollte, wären wir gut beraten, alles dafür zu tun, sie als Verbündete zu gewinnen.", completion = "Es sind wundervolle Lebewesen... Sie sind ganz rein und eins mit der Welt. Ich hätte nicht gedacht, dass ich die Legion noch mehr hassen könnte.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37451] = { id = 37451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Qiana Moonshadow (Follower Mission Turn in)" }
quests[37452] = { id = 37452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Apexiskristallhaufen", progress = "Doppelt so teuer wie das letzte, aber vielleicht ist es den Preis ja wert. Oder wäre Euch eine andere Währung genehmer? Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich vielleicht andere Siegel.", completion = "Ich wusste, wir verstehen uns." }
quests[37453] = { id = 37453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Apexiskristallberg", progress = "Vier Mal so teuer wie das erste, aber nur ein Siegel. Denkt dran, dass ich auch effizientere Optionen anbiete, obwohl ich niemals jemanden ablehne, der darauf besteht, mir mehr zu geben. Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich vielleicht andere Siegel.", completion = "Ich wusste, wir verstehen uns." }
quests[37454] = { id = 37454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Haufen von Goldmünzen", progress = "Doppelt so teuer wie das letzte, aber vielleicht ist es den Preis ja wert. Oder wäre Euch eine andere Währung genehmer? Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich vielleicht andere Siegel.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
