quests[37456] = { id = 37456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Eingelagerte Garnisonsressourcen", progress = "Doppelt so teuer wie das letzte, aber vielleicht ist es den Preis ja wert. Oder wäre Euch eine andere Währung genehmer? Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich vielleicht andere Siegel.", completion = "Fühlt Ihr Euch sicher, Fremder?" }
