quests[37466] = { id = 37466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verheerte Akademie" }
quests[37467] = { id = 37467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Schmach", description = "Der Widerhall von Nar'thalas verfolgt mich immer noch und ich kann das Leid dieser verfluchten Stadt nicht mehr ertragen. Aber ich kann Euch vielleicht immer noch helfen, an den Gezeitenstein zu gelangen.\n\n<Farondis' Entschlossenheit ist zurückgekehrt und seine Augen verengen sich.>\n\nWir müssen uns am Rand der Stadt entlangbewegen. Folgt mir.", sourceObjective = "Begleitet Prinz Farondis am Rand der Stadt Nar'thalas entlang.", completion = "<Der Prinz wirkt emotional erschöpft.>\n\nHier endet mein Weg, {name}. Ich ertrage es nicht, sie anzuschauen. Und noch schlimmer ist, dass allein meine Anwesenheit Euch in Gefahr bringt.\n\nVon hier aus müsst Ihr allein weitergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37468] = { id = 37468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Akademie", description = "Das versunkene Gebäude auf der anderen Seite der Brücke wurde einst die Akademie von Nar'thalas genannt. Sie war das Zentrum aller magischen Studien in ganz Azeroth. Ihr hättet sie zu ihren prachtvollsten Zeiten sehen sollen.\n\nDarin sollte sich der Gezeitenstein befinden. Ich selbst traue mich dort nicht hinein. Aber Ihr, mein Champion, habt meinen Segen und könnt gehen.", sourceObjective = "Betretet die Hallen der Akademie von Nar'thalas.", completion = "Ein neuer Schüler?", sourceObjectiveStatus = "unverified-source-field" }
quests[37469] = { id = 37469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gezeitenstein: Zersplittert", description = "Dann könnt Ihr wohl eintreten.\n\nDie zerschmetterten Teile von Golganneths Gezeitenstein werden im Ostflügel der Akademie verwahrt. Selbst als der zuständige Kurator kann ich nichts über ihren Zustand sagen, denn ich war seit Jahrtausenden nicht mehr dort drin.\n\nUnd noch etwas, {name}... Bitte nichts anfassen, ja?", sourceObjective = "Sammelt 5 Splitter des Gezeitensteins ein.", progress = "<Das letzte verbleibende Teil des Gezeitensteins liegt vor Euch.>", completion = "<Ihr bemerkt den Widerschein von etwas Bösem auf der Oberfläche des Kerns...>", sourceObjectiveStatus = "unverified-source-field" }
quests[37470] = { id = 37470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kopf der Schlange", description = "Diese Naga haben die Splitter des Gezeitensteins, {name}. Sie werden sie schon bald in ihren nassen Löchern verstecken, wo wir sie nie erreichen können.\n\nEs wäre klug, ihre Anführerinnen auszuschalten, bevor sie sich zurückziehen.", sourceObjective = "Besiegt Athissa.", completion = "Ihr habt Athissa getötet, {name}.\n\nAlso Ihr und... und mein Volk...\n\nMein Volk... Es hat für uns gekämpft...\n\nAber Kriegsherr Parjesh ist mit dem Gezeitenstein durch das Portal entkommen. Ihr müsst ihn verfolgen und die Säule der Schöpfung zurückholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37471] = { id = 37471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dahrok Boneshatter" }
quests[37472] = { id = 37472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gortag Steelgrip" }
quests[37473] = { id = 37473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Krahl Deathwind" }
quests[37474] = { id = 37474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst die Grundlagen", description = "Euer Enthusiasmus ehrt Euch, {name}, aber Ihr müsst erst die Grundlagen des Haustierkampfs erlernen. Besucht Marlene Trichdie in Sturmwind, damit sie Euch beim Einstieg hilft.", sourceObjective = "Sprecht mit Marlene Trichdie in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[37475] = { id = 37475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmolzene Steinbruch" }
