quests[37483] = { id = 37483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmannspfeife", sourceObjective = "Bringt Anne Dunworthy 100 Artefaktfragmente für eine Hauptmannspfeife.", sourceObjectiveStatus = "unverified-source-field" }
quests[37484] = { id = 37484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmannspfeife", sourceObjective = "Bringt Anne Dunworthy 100 Artefaktfragmente für eine Hauptmannspfeife.", sourceObjectiveStatus = "unverified-source-field" }
quests[37485] = { id = 37485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[37486] = { id = 37486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nar'thalas leidet immer noch", description = "Sie haben mir noch nicht vergeben. Ich kann es ihnen nicht verdenken.\n\nAber von den Verbrechen der Vergangenheit abgesehen bin ich immer noch ihr Prinz. Selbst im Tod werde ich alles tun, um mein Volk zu beschützen.\n\n{name}, seid mein Champion. Findet und erledigt die Kreatur, die diesen Nagaangriff gegen das Volk von Nar'thalas anführt. Nach all den Jahren werdet ausgerechnet Ihr, <ein/eine:r> {race}, das Werkzeug meiner Rache sein.", sourceObjective = "Besiegt Athissa.", completion = "Sie hat vom Gezeitenstein gesprochen? Diese Seehexe hat ja keine Ahnung, wie nahe sie an ihm dran ist.\n\nWir sollten uns beeilen. Wir haben es fast geschafft, aber die Naga kommen immer näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[37492] = { id = 37492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ziemlich langer Spaziergang", description = "Ich mache mir Sorgen um den Ältesten Aldryth. Er ist vor ungefähr zehntausend Jahren zu einem Spaziergang aufgebrochen und noch nicht wieder zurück.\n\nIch fürchte, dass er von diesen Naga angegriffen werden könnte!\n\nBitte haltet Ausschau nach dem Hofältesten, wenn Ihr Euch dort ins Gefecht hinauswagt.", sourceObjective = "Sucht nach dem Ältesten Aldryth.", completion = "Ihr könnt Euch gar nicht vorstellen, wie erleichtert ich bin, dass der Älteste Aldryth wieder da ist.\n\nGanz ehrlich, das Leben hier am Hofe war ohne ihn nicht dasselbe. Alles schien... seine Farbe verloren zu haben. Vielleicht können wir ja jetzt wieder ein normales Leben führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37493] = { id = 37493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Morphed Sentient" }
quests[37494] = { id = 37494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schutz der Dunkelheit", description = "Wir machen uns jetzt auf den Weg nach Sturmwind. Tethys wird uns heute Nacht im Schutz der Dunkelheit auf dem Wasserweg unter den alten Kasernen einschleusen.\n\nDer Rest liegt dann bei Euch, Mathias und mir. Wir müssen uns einen Weg durch Sturmwind suchen und Detheroc beim SI:7 stellen... und das, ohne Aufsehen zu erregen.\n\nSeid Ihr bereit für diese Aufgabe, {name}?", sourceObjective = "Sprecht mit Taoshi, sobald Euch Flottenadmiral Tethys nach Sturmwind bringen soll.", completion = "Wir haben es geschafft. Jetzt müssen wir es nur noch bis nach oben schaffen, durch meine Stadt schleichen, auf die sich im Moment übrigens die Augen aller richten, und dann einen Schreckenslord enttarnen und töten, der sich im Hauptquartier des SI:7 versteckt, dem wohl besten Spionagenetzwerk von Azeroth.\n\nEin echtes Kinderspiel. Seid Ihr bereit, die Welt zu retten, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[37495] = { id = 37495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündert die Höhle" }
quests[37496] = { id = 37496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltriert die Schiffbrucharena", description = "Die Riesen an der Schiffbrucharena haben große Freude daran, Schiffe zu zerstören, die dem Ufer zu nahe kommen. Sie nehmen die Matrosen gefangen und missbrauchen sie zu ihrem eigenen Vergnügen.\n\nIch vermute, dass Ihr dort mit Leichtigkeit eindringen könnt. Das Ausbrechen könnte schon schwieriger werden.", sourceObjective = "Infiltriert die Schiffbrucharena und findet Okuna Langhauer.", completion = "Habt Ihr die Flasche erhalten? Seid Ihr hier, um uns bei der Flucht zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[37497] = { id = 37497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Spur des Gezeitensteins", description = "Eure Suche nach dem Gezeitenstein... fasziniert mich. Mehr noch, sie kommt mir sogar sehr gelegen, denn ich bin schon seit sehr, sehr langer Zeit auf der Suche nach einem Champion.\n\nDamit steht es also fest. Ich werde Euch begleiten.\n\nWir müssen nach Osten durch Nar'thalas.\n\nWollen wir aufbrechen?", sourceObjective = "Begleitet Prinz Farondis zu den Ruinen von Nar'thalas.", completion = "Vielleicht war das ein Fehler.", sourceObjectiveStatus = "unverified-source-field" }
quests[37501] = { id = 37501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Challenge Mode - Bronze Addition (1st)" }
quests[37502] = { id = 37502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Challenge Mode - Consolation (1st)" }
