quests[37505] = { id = 37505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Draenor - Raid Finder - 1st" }
quests[37506] = { id = 37506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Draenor - Raid Finder - Nth" }
quests[37507] = { id = 37507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boss Walplauze hat das Sagen", description = "Sehr gut, dann fangen wir an! Wenn wir hier ausbrechen wollen, müsst Ihr Euch als <Grubenkämpfer/Grubenkämpferin> ausgeben, genau wie wir anderen. Die werden Euch nicht einfach hier herumlaufen lassen, wie es Euch gefällt.\n\nDazu müsst Ihr zuerst mit Boss Walplauze sprechen. Die Riesen haben hier zwar das Sagen, aber in Sachen Grubenkampf ist Walplauze der Chef.\n\nEr spricht etwas südlich von hier gerade mit seinen Untergebenen.", sourceObjective = "Sprecht mit Boss Walplauze.", progress = "Na los. Sprecht ihn an.", completion = "Das ist nicht so gut gelaufen. Offensichtlich habt Ihr Euch bereits einen Feind gemacht.\n\nAber das könnte auch ein Vorteil sein. Ihr gegen Boss Walplauze. Der Kampf des Jahrhunderts... oder wenigstens des Tages.\n\nJetzt müssen wir nur noch alles vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37508] = { id = 37508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Stacking the Deck" }
quests[37509] = { id = 37509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Stacking the Deck" }
quests[37510] = { id = 37510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hecktiefs Champion", description = "Da Ihr den Knatzelfiddler besiegt habt, ist Platz für einen weiteren Grubenkämpfer im Team von Hecktief. Ihr solltet versuchen, sein Champion zu werden. Dann werden die Riesen nicht weiter darüber nachdenken, warum <ein Fremder/eine Fremde> plötzlich kommt und geht, wie es <ihm/ihr> beliebt.\n\nIn der Zwischenzeit werde ich für etwas Chaos sorgen, damit wir Prinz Ozeanus angreifen können.", sourceObjective = "Meldet Euch als <neuer Grubenkämpfer/neue Grubenkämpferin> bei Hecktief.", completion = "Hallo, was kann ich denn für Euch tun, kleiner {race}?\n\nHahaha... Ihr seid es! Das hat mir gut gefallen, wie Ihr reingekommen seid und es gleich mit Walplauze aufgenommen habt. Dieser kleine Tuskarr hat es nicht besser verdient.\n\nIch weiß jetzt schon, dass Ihr für mich in der Arena siegen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[37511] = { id = 37511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dizzy Zündbolz", description = "Ich stehe nicht so schlecht da, was Artefakte angeht.\n\nEin paar andere Werterhalter sind auch hier draußen. Ich würde sie ja gerne suchen, aber ich glaube, ich würde meiner Gesundheit damit keinen Gefallen tun.\n\nEuch macht Schmerz doch nichts aus, wollt Ihr nicht Dizzy suchen gehen?", sourceObjective = "Findet Dizzy Zündbolz.", completion = "Pssst... leise. Ich will keine Ogerfaust ins Gesicht kriegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37516] = { id = 37516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Nixxie", description = "Nixxie macht sich bestimmt riesige Sorgen, dass sie wegen dieser Vermessungsoperation Profiteinbußen machen könnte.\n\nFalls Ihr sie seht, könntet Ihr ihr sagen, dass wir ziemlich bald zurück sein werden?", sourceObjective = "Sprecht mit Nixxie.", completion = "Es hört sich so an, als wäre die Ausgrabung auf der Zerschlagenen Anhöhe schon sehr bald vollständig einsatzbereit.\n\nIch kann es kaum erwarten, dass Knete in meine Taschen wandert.", sourceObjectiveStatus = "unverified-source-field" }
quests[37517] = { id = 37517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Nixxie", description = "Nixxie macht sich bestimmt riesige Sorgen, dass sie wegen dieser Vermessungsoperation Profiteinbußen machen könnte.\n\nFalls Ihr sie seht, könnt Ihr ihr sagen, dass wir ziemlich bald zurück sein werden?", sourceObjective = "Sprecht mit Nixxie.", completion = "Es hört sich so an, als wäre die Ausgrabung auf der Zerschlagenen Anhöhe schon sehr bald in vollem Betrieb.\n\nIch kann es kaum erwarten, dass die Knete in meine Taschen wandert.", sourceObjectiveStatus = "unverified-source-field" }
quests[37518] = { id = 37518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfluchten Hallen", description = "Was wolltet Ihr noch gleich? Ihr seid hier, um Euch Golganneths Gezeitenstein anzusehen? Hah! Ho ho ha ha haa!\n\nOoooh Mann.\n\nNein, nur die Direktorin der Akademie hat den Schlüssel zu dieser Kammer, und sie hat diese Tür in... hm, ich würde sagen, in den letzten zehntausend Jahren nicht mehr geöffnet.\n\nUnd jetzt solltet Ihr Euch zum Unterricht aufmachen! Na los! Ab in den Westflügel!", sourceObjective = "Begebt Euch in den Westflügel der Akademie.", completion = "Ja, die Direktorin ist in ihrem Studierzimmer, aber Ihr dürft sie jetzt nicht stören. Der Unterricht wird gleich beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37520] = { id = 37520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gräuelklaues Klaue", progress = "Gräuelklaue, ein erbarmungsloses Raubtier, wird in ganz Nagrand gefürchtet. Sie ist zwar einer der gefährlichsten Raptoren, der Euch je begegnen wird, doch auf eine wilde Art ist sie schön.\n\nGräuelklaue muss erhalten werden, damit auch zukünftige Generationen sie bestaunen können! Wenn Ihr mir eine ihrer messerscharfen Klauen bringt, sorge ich dafür, dass es sich für Euch lohnt.", completion = "Gute Arbeit, {name}!\n\nIn Momenten wie diesem bin ich stolz, Euer Mentor zu sein. Aus Euch wird noch ein hervorragender Archäologe!\n\nHier, Euer Anteil." }
quests[37523] = { id = 37523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Gorianische Übungsgelände", description = "Die Oger auf dem gorianischen Übungsgelände bilden Champions aus, die unsere Streitkräfte in Nagrand bekämpfen sollen.\n\nWenn wir das Übungsgelände gezielt angreifen, werden die Oger nicht genug Truppen haben, um gegen uns vorzugehen. Gleichzeitig erinnern wir sie daran, dass sie uns nicht als Feind wollen.", sourceObjective = "Greift die Oger auf dem gorianischen Übungsgelände in Nagrand an.", sourceObjectiveStatus = "unverified-source-field" }
quests[37524] = { id = 37524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das gorianische Übungsgelände", description = "Die Oger auf dem gorianischen Übungsgelände bilden Champions aus und wollen unsere Streitkräfte in Nagrand bekämpfen.\n\nWenn wir das Übungsgelände direkt angreifen, werden die Oger nicht genug Truppen haben, um gegen uns vorzugehen. Gleichzeitig kriegen sie eine Erinnerung, dass sie uns nicht als Feind wollen.", sourceObjective = "Greift die Oger auf dem gorianischen Übungsgelände in Nagrand an.", sourceObjectiveStatus = "unverified-source-field" }
quests[37525] = { id = 37525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ak'ox the Slaughterer" }
quests[37526] = { id = 37526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farondis Murder Flag" }
quests[37528] = { id = 37528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Riesen soll man nicht wecken", description = "Wir müssen für Ablenkung sorgen, um an Prinz Ozeanus heranzukommen. Denken wir gerade das Gleiche?\n\nSeht Ihr den Schläfrigen Dhau da drüben? Er bewacht all die Waffen, die die Riesen aus unseren Schiffen gestohlen haben. Damit können wir den Rest der Grubenkämpfer bewaffnen, die in den Höhlen gefangen gehalten werden.\n\nIhr müsst nur an diesem Riesen vorbeikommen, ohne ihn aufzuwecken.", sourceObjective = "Sammelt den Waffenvorrat der Riesen ein.", progress = "So bald ich kann, werde ich die Gladiatoren in Ozeanus' Bucht bewaffnen.", completion = "Ich hätte mich nicht besser an ihm vorbeischleichen können. Und jetzt geben wir diese Waffen in die richtigen Hände.", sourceObjectiveStatus = "unverified-source-field" }
quests[37530] = { id = 37530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Euch", description = "Natürlich konnte ich nicht einfach nur zusehen, wie sie Euch davonkarren.\n\nIch werde Euch alles erklären.", sourceObjective = "Sprecht mit Farondis und lasst ihn erzählen, wie er Euch gerettet hat.", progress = "Ich will Euch zeigen, was passiert ist.", completion = "Was ist geschehen, Farondis?", sourceObjectiveStatus = "unverified-source-field" }
quests[37531] = { id = 37531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking - See Closed Chest" }
quests[37532] = { id = 37532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Splitter", description = "Bevor ich es vergesse, {name}: die Splitter des Gezeitensteins. Von jetzt an werdet Ihr sie beschützen.\n\nBringt sie Eurem Drachen. Das Volk von Azsuna steht hinter Euch.", sourceObjective = "Bringt die Splitter des Gezeitensteins zu Senegos.", sourceObjectiveStatus = "unverified-source-field" }
quests[37536] = { id = 37536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moralschub", description = "Aus Eurer Warte sieht es vielleicht ganz gut aus, aber wir verlieren. Aber fürchtet Euch nicht, <mein kleiner/meine kleine:r> {race}.\n\nIn der Höhle der Champions ist die Knatzelfiddlerin, die Schwester vom Knatzelfiddler. Sie bereitet dort gerade ihr weltberühmtes Soldatenfutter zu. Damit können wir die Moral unseres Teams entscheidend steigern.\n\nIhr müsst sie einfach nur überzeugen, es rauszurücken.", sourceObjective = "Besorgt das Soldatenfutter von der Knatzelfiddlerin.", completion = "Ja, das sollte funktionieren... Oh, nein! Der letzte meiner Grubenkämpfer ist gerade besiegt worden.\n\nJetzt sind nur noch wir beide übrig, kleiner {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37537] = { id = 37537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravyn-Drath" }
quests[37538] = { id = 37538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 1, Kampf!", description = "Alle meine Gladiatoren sind ausgefallen!\n\nJetzt kommt es auf Euch an, {name}. Ihr müsst gegen die drei Champions von Kimmruder antreten.", sourceObjective = "Tretet für Hecktief in der Arena an, besiegt Boss Walplauze und sucht dann Okuna Langhauer in Ozeanus' Bucht auf.", completion = "<Hier hättet Ihr Okuna finden sollen. Stattdessen habt Ihr nur die Waffen gefunden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37540] = { id = 37540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz des Eisernen Eroberers", description = "Löst Eure Essenz des Eisernen Eroberers bei Lady Liadrin ein, um einen Rüstungsgegenstand Eurer Wahl zu erhalten.", sourceObjective = "Erhaltet eine Essenz des Eisernen Eroberers.", progress = "Здравствуй, |3-6(Чернокнижница). Вижу, в недавних сражениях тебе удалось добыть ценный трофей.", completion = "Блэквизард, благодаря твоей храбрости и самоотверженности на Дреноре стало хоть немного спокойнее. Прими эту награду. И да озарит Свет твой путь.", sourceObjectiveStatus = "unverified-source-field" }
quests[37541] = { id = 37541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz des Eisernen Bezwingers", description = "Löst Eure Essenz des Eisernen Bezwingers bei Lady Liadrin ein, um einen Rüstungsgegenstand Eurer Wahl zu erhalten.", sourceObjective = "Erhaltet eine Essenz des Eisernen Bezwingers.", progress = "Ich grüße Euch, {class}. Wie ich sehe, habt Ihr in Euren letzten Schlachten eine Trophäe in Euren Besitz gebracht.", completion = "{name}, Euer Mut und Eure Hingabe haben Draenor zu einem sichereren Ort gemacht. Nehmt diese Ausrüstung und wandelt im Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37542] = { id = 37542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Vorbereitung", description = "Wir haben nicht viel Zeit, um Euch vorzubereiten. Aber die Arenakämpfe sind die beste Möglichkeit, Euch mit den Riesen gut zu stellen.\n\nDieser warmherzige Riese, der da drüben gerade gegen Kimmruder verliert, heißt Hecktief. Wenn Ihr seinen Ho-zen-Champion besiegt, wird ein Platz für Euch in seinem Team frei.\n\nDer Knatzelfiddler scheint gerade ein Päuschen einzulegen. Jetzt könnt Ihr dem Affen so richtig einen auf den Pelz geben.", sourceObjective = "Verabreicht dem Knatzelfiddler eine Tracht Prügel.", completion = "Mit diesem Affen habt Ihr kurzen Prozess gemacht. Jetzt ist in Hecktiefs Team eine Position frei, die Ihr einnehmen könnt.\n\nAber zunächst will ich Euch auf das vorbereiten, was Euch nach dem großen Kampf erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[37543] = { id = 37543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz des Eisernen Beschützers", description = "Löst Eure Essenz des Eisernen Beschützers bei Lady Liadrin ein, um einen Rüstungsgegenstand Eurer Wahl zu erhalten.", sourceObjective = "Erhaltet eine Essenz des Eisernen Beschützers.", progress = "Ich grüße Euch, {class}. Wie ich sehe, habt Ihr in Euren letzten Schlachten eine Trophäe in Euren Besitz gebracht.", completion = "{name}, Euer Mut und Eure Hingabe haben Draenor zu einem sichereren Ort gemacht. Nehmt diese Ausrüstung und wandelt im Licht.", sourceObjectiveStatus = "unverified-source-field" }
