quests[37563] = { id = 37563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Frostwölfe sind bereit.", description = "Obwohl wir heute viel verloren haben, sind die Frostwölfe bereit, unseren Pakt mit Eurem Volk zu erfüllen.\n\nUm diese Übereinkunft einzuhalten haben einige meiner Klansmitglieder darum gebeten, sich Euch anschließen und Seite an Seite mit Euren Truppen kämpfen zu dürfen.\n\nUnsere Reihen haben sich gelichtet, also bitte ich Euch, nur einen von ihnen auszuwählen. Sprecht mit mir, wenn Ihr Eure Entscheidung getroffen habt.", sourceObjective = "Wählt einen Anhänger (entweder Großmutter Geyah, Kal'gor den Ehrenhaften oder Lokra) und sprecht dann mit Makar Steinbinder.", completion = "Eine Exzellente Wahl. Es wird mir schwerfallen, Abschied zu nehmen, doch ich weiß, dass diese Hilfe unsere gemeinsamen Rudel in zukünftigen Schlachten stärker machen wird.\n\nIch werde dafür sorgen, dass Euer neuer Anhänger sich zu Eurer Garnison begibt, sobald er sich von seiner Familie verabschiedet hat.\n\nWenn Ihr das nächste Mal Anhänger auf eine Mission schickt, sollte er zu Eurer Verfügung stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37564] = { id = 37564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Schmiedekunst", description = "Jetzt, da Ihr über eine Schmiede verfügt, können wir Echtstahlbarren für Euch fertigen. Sprecht mit meinem Gehilfen, wenn Ihr die Bestandteile für den ersten Arbeitsauftrag zusammengetragen habt, sodass wir damit beginnen können.", sourceObjective = "Beginnt Euren ersten Schmiedekunstarbeitsauftrag in der Schmiede und holt in anschließend ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37565] = { id = 37565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau die richtige Waffe", description = "<Ihr und Okuna wolltet die Gefangenen hier drin bewaffnen. Die Idee war, sie zu befreien und so viel Chaos wie möglich anzurichten. Das ist die einzige Möglichkeit, an den Prinzen heranzukommen.\n\nIhr habt immer noch die Waffen. Ihr müsst Euch nur vorsichtig an den Riesen vorbeischleichen.>", sourceObjective = "Bewaffnet 25 schiffbrüchige Gefangene.", completion = "Die Gefangenen sind jetzt frei. Ich danke Euch, {name}.\n\nSeid Ihr jetzt bereit für den Prinzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[37566] = { id = 37566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Prinzen", description = "{name}! Ich wusste, dass Ihr kommen würdet.\n\nSchnell, lasst mich hier raus, damit wir diesen Riesen erledigen können.", sourceObjective = "Befreit Okuna Langhauer und tötet Prinz Ozeanus.", completion = "Nach Oceanus' Tod werden Kämpfe unter den Skrogs ausbrechen. Damit sind sie ganz sicher zu beschäftigt, um die Naga weiter zu unterstützen.\n\nDas war gute Arbeit, trotz meiner Gefangenschaft. Gut, dass Ihr hier vorbeigekommen seid.\n\nAlso bis dann, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37567] = { id = 37567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interact with Dudebro" }
quests[37568] = { id = 37568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Alchemie", description = "Jetzt, da Ihr über ein Alchemielabor verfügt, können wir alchemistische Katalysatoren für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Abeitsauftrag für Alchemie beim Alchemielabor und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37569] = { id = 37569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Schmiedekunst", description = "Jetzt, da Ihr über eine Schmiede verfügt, können wir Echtstahlbarren für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile für den ersten Arbeitsauftrag zusammengetragen habt, damit wir beginnen können.", sourceObjective = "Beginnt Euren ersten Schmiedekunstarbeitsauftrag in der Schmiede und holt in anschließend ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37570] = { id = 37570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Verzauberkunst", description = "Jetzt, da Ihr über ein Verzauberungsatelier verfügt, können wir draenischen Staub für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Verzauberkunst beim Verzauberungsatelier und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37571] = { id = 37571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Ingenieurskunst", description = "Jetzt, da das Ingenieurlabor fertig ist, kann die Produktion von Getriebefederteile anlaufen! Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile habt, dann können wir gleich mit dem ersten Arbeitsauftrag loslegen.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Ingenieurskunst beim Ingenieurlabor und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37572] = { id = 37572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Inschriftenkunde", description = "Jetzt, da Ihr über eine Schreibstube verfügt, können wir Kriegsfarben für Euch herstellen. Sprecht mit meinem Gehilfen, wenn Ihr die Zutaten zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag anfangen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Inschriftenkunde bei der Schreibstube und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37573] = { id = 37573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Juwelierskunst", description = "Jetzt, da Ihr über eine Juwelenschleiferei verfügt, können wir Taladitkristalle für Euch fertigen. Sprecht mit meinem Gehilfen, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Juwelierskunst bei der Juwelenschleiferei und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37574] = { id = 37574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Lederverarbeitung", description = "Jetzt, da Ihr über eine Gerberei verfügt, können wir poliertes Leder für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Lederverarbeitung bei der Gerberei und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37575] = { id = 37575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Schneiderei", description = "Jetzt, da Eure Maßschneiderei fertiggestellt ist, können wir Hexenzwirn für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Schneiderei bei der Maßschneiderei und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37584] = { id = 37584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer zweiter Arbeitsauftrag für Alchemie", description = "Erteilt meiner Gehilfin einen weiteren Auftrag. Sobald er fertig ist, könnt Ihr ihn hier abholen.", sourceObjective = "Erteilt einen Arbeitsauftrag und holt ihn nach Abschluss ab.\n\nIhr könnt den Fortschritt über das Garnisonsberichtsfenster verfolgen, das über die Schaltfläche auf der Minikarte aufrufbar ist.", sourceObjectiveStatus = "unverified-source-field" }
