quests[37652] = { id = 37652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Jabberjaw" }
quests[37653] = { id = 37653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenseelen", description = "Ich muss diesen widerwärtigen Kreaturen Informationen über die Brennende Legion entlocken. Aber im lebendigen Zustand lassen die Dämonen sich kaum brechen.\n\nGenau wie Ihr bin jedoch auch ich im Besitz eines mächtigen Artefakts, der Seelensense.\n\nNehmt einen meiner Seelenedelsteine. Wenn Ihr ihn neben die Leiche eines Dämons legt, wird er ihm die \"Seele\" herausreißen. Und dann werden wir herausfinden, ob die Sense ihn zum Sprechen bringt.", sourceObjective = "Setzt 8 Dämonenseelen an der Faronaarfront fest.", progress = "Wir brauchen diese Dämonenseelen, {name}.", completion = "Ja, schon jetzt spüre ich, dass ihre Seelen schwächer als ihr Fleisch sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[37654] = { id = 37654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesetze des Meeres", description = "<Werter Herr/Werte Dame>, bitte gewährt mir einen Augenblick Eurer kostbaren Zeit. Meine Bergungskollegen und ich haben Euer Schiff bemerkt, das unglücklicherweise letzte Nacht im Sturm auf Grund gelaufen ist.\n\nTut mir sehr leid um die Crew.\n\n<Herr Fessel unterstreicht dies mit einer mitfühlenden Geste.>\n\nAber Gesetz ist Gesetz. Das Seeverkehrsrecht ist hier absolut eindeutig. Wenn Ihr trotzdem noch ein paar Sachen bergen wollt, wäret Ihr dann vielleicht so liebenswürdig, nach meinem Akquise-Scout Looper Ausschau zu halten? Er hätte schon vor einer Weile pünktlich zum Nachmittagstee zurück sein sollen.", sourceObjective = "Sucht nach Looper Allen in der Nähe des Schiffes, das an der Ostküste von Mak'rana auf Grund gelaufen ist.", completion = "Wisst Ihr eigentlich, was für ein Schiff das ist? Das ist die \"Revanche der Königin\". Königin... wie in Bansheekönigin, Sylvanas Windläufer.\n\nWenn das Gehöft nicht in den Fluten versunken wäre, wäre ich jetzt auf dem Nachhauseweg nach Gilneas.", sourceObjectiveStatus = "unverified-source-field" }
quests[37656] = { id = 37656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Machenschaften", description = "Meine Truppen haben den Vorposten der Dämonen hier ausgelöscht, aber eine Wichtelmutter und ihre Brut haben meine überlebenden Dämonenjäger einschließlich Cyana Nachtgleve als Geiseln genommen.\n\nWir müssen die Illidari befreien und die Brennende Legion vernichten.", sourceObjective = "Befreit 6 Dämonenjäger aus den Seelenerntern.", progress = "Wenn wir die Legion besiegen wollen, müssen wir genau wissen, was sie eigentlich vorhaben.", completion = "Ich hatte immer meine Zweifel an Cyana. Irgendetwas stimmte mit ihr nicht. Wie es aussieht, ist sie ins Wanken gekommen und hat sich der Legion angeschlossen.\n\nTrotzdem werden wir nicht zulassen, dass sie oder diese Cordana Teufelsang damit davonkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37657] = { id = 37657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sichere Handelswelt schaffen", description = "Kann ich Euch um einen kleinen Gefallen bitten, <mein Freund/meine Freundin>? Diese Kreaturen in den Gezeitenteichen im Osten fangen an, mich zu ängstigen. Unsere Handelsangebote an sie wurden jedes Mal aggressiv abgeschmettert. Das ist nicht gut, weder fürs Geschäft noch für den Profit.\n\nLeider muss ich eingestehen, dass die Zeit für Verhandlungen vorbei ist.\n\nWärt Ihr gewillt, als <mein Repräsentant/meine Repräsentantin> zu fungieren und Euch um die Bewohner von Mak'rana und ihre \"Königin\" zu kümmern?\n\nIch kann Euch versichern, dass Eure Anstrengungen angemessen vergütet werden.", sourceObjective = "Tötet 12 Gilblin und/oder Makrura in Mak'rana und tötet ihre Anführerin, Königin Kraklaa.", progress = "Wie geht es mit dem Aufräumen voran?", completion = "Was? Ein Wärterdämon, sagt Ihr? Oublion? Was für ein schrecklicher Name.\n\nKein Wunder, dass wir keine Handelspartner werden konnten. Oh, wenn ich das gewusst hätte, wäre es nicht zu all dem Mord und Totschlag gekommen.\n\nNa ja. Leben und lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37658] = { id = 37658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederentzündung der Zauberschutze", description = "Die Dämonen schwächen meine Verteidigung. Sie scheinen viel mächtiger zu sein als jene, denen wir zuvor begegnet sind.\n\nKönnt Ihr mir helfen, die Zauberschutze neu zu entzünden und zu verhindern, dass die Legion unsere Stellung hier überrennt?", sourceObjective = "Zündet 3 Dämonenzauberschutze neu an.", progress = "Alle Zauberschutze müssen neu entzündet werden, wenn wir die Front halten wollen.", completion = "Ich danke Euch, {name}. Das wird uns ausreichend Zeit verschaffen, um unseren Gegenangriff zu starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37659] = { id = 37659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schließkiste des Kapitäns", description = "Mir ist es egal, was Ihr treibt, <mein Lieber/meine Liebe>. Aber wenn sie Euch erwischen, kenne ich Euch nicht.\n\nIch war gar nicht hier.", sourceObjective = "Sucht nach der Kiste des Kapitäns auf den unteren Decks der \"Revanche der Königin\".", completion = "<Unter den modrigen Überresten der Kiste findet Ihr das Logbuch des Kapitäns. Die Seiten sind teilweise noch lesbar und enthalten interessante Informationen über den möglichen Aufenthaltsort von Königin Sylvanas Windläufer, dem neuen Kriegshäuptling der Horde.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37660] = { id = 37660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelensense", description = "Gehen wir auf die andere Seite der Tribüne. Wir werden die Dämonenseelen eine nach der anderen freilassen und dann die Antworten bezüglich Fürst Illidan bekommen.\n\nDafür wird die Seelensense schon sorgen.", sourceObjective = "Arbeitet mit Allari der Seelenfresserin zusammen, um die Informationen von den Dämonenseelen zu bekommen.", progress = "Wir müssen die Dämonen zwingen, {name}.", completion = "Ich würde Arev'naals Worte nicht allzu ernst nehmen. Diese Inquisitordämonen sind wahre Meister der Desinformation. Ihr glaubt doch nicht ernsthaft an Verräter in Euren eigenen Reihen, oder?\n\n<Die Seelenfresserin blickt nachdenklich und besorgt drein.>\n\nIch fürchte, es wird noch eine Weile dauern, bis wir alle Antworten zu Fürst Illidan erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37666] = { id = 37666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf einen Kampf aus", description = "Sie kommen, {name}!\n\nIch werde den Käfig von diesen Ketten aus teuflischer Magie befreien.\n\nIhr haltet mir die Legion vom Hals.", sourceObjective = "Tötet so lange Dämonen, bis Verlieswächter Umbral erscheint, und dann auch ihn. Befreit anschließend Mathias Shaw.", completion = "Ich bin Euch auf ewig dankbar, {name}. Niemand soll behaupten, dass ich den Einfluss und das Geschick der Ungekrönten unterschätzt habe.\n\nDer einfache Teil wäre somit erledigt. Jetzt gilt es, das Unmögliche zu wagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37667] = { id = 37667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufsgebäude", description = "Ich sehe, dass Ihr die Pläne für ein Handwerksgebäude erworben habt! Nutzt den Architektentisch, um es auf einem kleinen Bauplatz zu errichten.", sourceObjective = "Errichtet ein beliebiges Handwerksgebäude.", sourceObjectiveStatus = "unverified-source-field" }
quests[37669] = { id = 37669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksgebäude", description = "Ich sehe, dass Ihr die Pläne für ein Handwerksgebäude erworben habt! Nutzt den Architektentisch, um es auf einem kleinen Bauplatz zu errichten.", sourceObjective = "Errichtet ein beliebiges Handwerksgebäude.", completion = "Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
