quests[37678] = { id = 37678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuschlagen statt nachschlagen", description = "<Die Bibliothekarin spricht leise mit Euch.>\n\nEin Problem beim Betreiben einer solch großen arkanen Bibliothek besteht darin, dass die Bücher oft die ein oder andere unvorsichtig ausgesprochene Verzauberung aufnehmen und dann anfangen, von sich aus herumzufliegen. Diese magisch übersättigten Bücher müssen zerstört werden, bevor sie größeren Schaden anrichten.\n\nWenn Ihr einem von diesen entnervenden Essays begegnen solltet, kümmert Euch bitte darum. Aber leise.", sourceObjective = "Zerstört 3 uralte Folianten.", progress = "<Die Bibliothekarin seufzt leise.>", completion = "Macht Euch keine Sorgen um die herumfliegenden Blätter und Buchrücken. Ich sorge dafür, dass meine Assistenten sie aufräumen.\n\nIch danke Euch. Ihr könnt zu Euren Studien zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
