quests[37684] = { id = 37684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[37687] = { id = 37687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: In den Schatten", description = "Ich brauche Eure Hilfe. Iskar wird vermisst. Ich habe Grund zu der Annahme, dass er den Überresten der Sethekk, die sich hier in Tanaan gesammelt haben, gefolgt ist. Ich habe das untersucht und... Was war das?\n\n<Reshad senkt seine Stimme zu einem Flüstern.>\n\nDa ist eine Bewegung in den Schatten. Wir werden beobachtet!\n\nNehmt diese Phiolen. Die Flüssigkeit setzt ein furchtbar stinkendes Gas frei, wenn sie mit Luft in Kontakt kommt. Das riecht wirklich übel, sie werden das nicht aushalten können. Treibt mit dem Gas unsere Beobachter aus ihrem Versteck.", sourceObjective = "Tötet 3 Nachtklingen des Rats in der Löwenwacht.", completion = "Also ist der Schattenrat darin verwickelt? Interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[37688] = { id = 37688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: In den Schatten", description = "Ich brauche Eure Hilfe. Iskar wird vermisst. Ich habe Grund zu der Annahme, dass er den Überresten der Sethekk, die sich hier in Tanaan gesammelt haben, gefolgt ist. Ich habe das untersucht und... Was war das?\n\n<Reshad senkt seine Stimme zu einem Flüstern.>\n\nDa ist eine Bewegung in den Schatten. Wir werden beobachtet!\n\nNehmt diese Phiolen. Die Flüssigkeit setzt ein furchtbar stinkendes Gas frei, wenn sie mit Luft in Kontakt kommt. Das riecht wirklich übel, sie werden das nicht aushalten können. Treibt mit dem Gas unsere Beobachter aus ihrem Versteck.", sourceObjective = "Tötet 3 Nachtklingen des Rats in Vol'mar.", completion = "Also ist der Schattenrat darin verwickelt? Interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[37689] = { id = 37689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Betrüger", description = "Detheroc hat die besten Scharfschützen des SI:7 auf den Dächern postiert. Wir können weder Reittiere einsetzen noch fliegen. Dort oben gibt es aber genügend Greifhakenziele, wir können also die Klippe erklimmen.\n\nWir haben außerdem Strohballen als Deckung entlang der wahrscheinlichsten Routen zum SI:7 platziert. Wir müssen uns nur hineinschleichen und Detheroc töten.\n\nSobald wir oben ankommen, teilen wir uns auf. Dadurch steigen unsere Chancen, dass einer es durch die Stadt schafft.\n\nViel Glück, {name}.", sourceObjective = "Erklimmt die Klippen an der Löwenruh mit Greifhaken, schleicht durch Sturmwind bis zum Hof des SI:7 und tötet Detheroc.", completion = "Ihr habt es geschafft! Der SI:7 untersteht endlich wieder dem Befehl von Mathias Shaw, und Ihr habt einen Krieg zwischen Allianz und Horde verhindert.\n\nWir alle sind uns einig, dass Ihr Euch als wertvolles Mitglied des Schattenrates und der Ungekrönten erwiesen habt.\n\nMeinen Glückwunsch, Schattenklinge {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[37690] = { id = 37690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erinnernden", description = "Einst waren die geisterhaften Elfen im Süden im Besitz der Säule der Schöpfung, die als Golganneths Gezeitenstein bekannt ist.\n\nIhre große Stadt Nar'thalas wurde in einem längst vergangenen Zeitalter zerstört. Der Herrscher der Stadt, Prinz Farondis, ging zusammen mit ihr unter. Ihr kleinen Wesen sterbt ja so leicht.\n\nWenn jemand weiß, wo sich die Fragmente befinden, dann der Geist dieses Prinzen. Macht Euch auf die Suche nach seinem Volk.", sourceObjective = "Sucht Nachtwächterin Idri in den Ertränkten Gärten auf.", completion = "Wer seid Ihr?\n\nEin Abgesandter aus dieser seltsamen, schwebenden Stadt?", sourceObjectiveStatus = "unverified-source-field" }
quests[37697] = { id = 37697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Goblin" }
quests[37713] = { id = 37713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 002 - El'dranil Tablet" }
quests[37726] = { id = 37726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiyaka the Stormbringer" }
quests[37727] = { id = 37727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Magister der Mixologie", description = "Ihr müsst wissen, dass ich ein Liebhaber exklusiver Tränke bin... insbesondere arkangesättigter Brände. Das Mixen von Cocktails ist Alchemie und Alchemie ist ja Magie, wie jeder weiß.\n\nMein neuester Trank muss exotischer als alle anderen zuvor werden. Ich habe dafür schon fast alles zusammen, was ich brauche. Es fehlen nur noch ein paar Zutaten auf der Liste.\n\nHabt Ihr die Reiher in der Lagune bemerkt? Wie viele andere Lebewesen in Azsuna werden auch sie von der Magie dieser Insel durchdrungen.\n\nIhre Eier sind genau das Richtige für mich.", sourceObjective = "Sammelt 6 arkangesättigte Eier ein.", progress = "Findet diese Konversation statt, weil Ihr die Eier habt?", completion = "Herausragend! Ein fantastischer Beginn.\n\nIch rate Euch dringlichst, diese famose Mixtur selbst herzustellen. Ich möchte das Vergnügen der alchemistischen Gebräue mit der ganzen Welt teilen!\n\nAllerdings müsst Ihr Euch erst noch ein paar Eier besorgen.", sourceObjectiveStatus = "unverified-source-field" }
